def solve():
    solutions = []
    for x1 in range(10):
        for y1 in range(10):
            for x2 in range(10):
                for y2 in range(10):
                    if 2**x2 * 5**y2 - 2**x1 * 5**y1 == 50:
                        solutions.append((x1, y1, x2, y2))
    return solutions

sols = solve()
print(f"Solutions (x1, y1, x2, y2): {sols}")

